contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value, "not enough ether");
        uint cBalBefore = address(c).balance;
        uint tBalBefore = target.balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint tBalAfter = target.balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            (
                reverted
                && cBalAfter == cBalBefore
                && tBalAfter == tBalBefore
                && depositsAfter == depositsBefore
            )
            ||
            (
                !reverted
                && cBalBefore >= value
                && cBalAfter + value == cBalBefore
                && tBalAfter == tBalBefore + value
                && depositsAfter == depositsBefore
            )
        );
    }

    receive() external payable {}
}

